using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Users;[Authorize(Policy="AccountAdmin")]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public IReadOnlyList<Row>Users{get;private set;}=[];public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid id)return Forbid();Users=await(from m in db.AccountMembers.AsNoTracking()join u in db.Users.AsNoTracking()on m.UserId equals u.Id where m.AccountId==id&&!m.IsDeleted&&!u.IsDeleted orderby u.Name select new Row(m.Id,u.Name,u.Email,m.RoleCode,m.Status.ToString(),u.LastLoginAt.HasValue?u.LastLoginAt.Value.ToString("g"):"Nunca")).ToListAsync(ct);return Page();}public sealed record Row(Guid MemberKey,string Name,string Email,string Profile,string Status,string LastLogin);}
